import { ProfilePatch } from './types';

function invalid(): never {
  throw new Error('invalid profile');
}

function hasOwn(object: object, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(object, key);
}

function isPlainObject(input: unknown): input is Record<string, unknown> {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) return false;
  const prototype = Object.getPrototypeOf(input);
  return prototype === Object.prototype || prototype === null;
}

export function parseProfile(input: unknown): ProfilePatch {
  if (!isPlainObject(input)) invalid();

  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') invalid();
  }

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  if (hasOwn(input, 'displayName')) {
    const value = input.displayName;
    if (value === null) {
      displayName = { kind: 'set', value: null };
    } else if (typeof value === 'string') {
      const trimmed = value.trim();
      if (trimmed.length < 1 || trimmed.length > 40) invalid();
      displayName = { kind: 'set', value: trimmed };
    } else {
      invalid();
    }
  }

  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  if (hasOwn(input, 'tags')) {
    const value = input.tags;
    if (value === null) {
      tags = { kind: 'set', value: [] };
    } else if (Array.isArray(value)) {
      if (value.length > 5) invalid();
      const parsedTags: string[] = [];
      const seen = new Set<string>();
      for (const item of value) {
        if (typeof item !== 'string') invalid();
        const trimmed = item.trim();
        if (trimmed.length < 1 || trimmed.length > 12) invalid();
        if (seen.has(trimmed)) invalid();
        seen.add(trimmed);
        parsedTags.push(trimmed);
      }
      tags = { kind: 'set', value: parsedTags };
    } else {
      invalid();
    }
  }

  return { displayName, tags };
}
